use zapapp_core::proto::node::{decode_binary_node, encode_binary_node};

fn hex_to_bytes(s: &str) -> Vec<u8> {
    (0..s.len())
        .step_by(2)
        .map(|i| u8::from_str_radix(&s[i..i + 2], 16).unwrap())
        .collect()
}

fn bytes_to_hex(bytes: &[u8]) -> String {
    bytes.iter().map(|b| format!("{:02x}", b)).collect()
}

#[test]
fn test_all_16_golden_fixtures_roundtrip() {
    let fixtures: &[(&str, &str)] = &[
        ("single-byte tokens as attr values", ""),
        ("dictionary 0 tokens as attr values", ""),
        ("dictionary 1 tokens as attr values", ""),
        ("dictionary 2 tokens as attr values", ""),
        ("dictionary 3 tokens as attr values", ""),
        ("tokens as tags", "f80213f828f80101f80102f80103f80104f80105f80106f80107f80108f80109f8010af8010bf8010cf8010df8010ef8010ff80110f80111f80112f80113f80114f80115f80116f80117f80118f80119f8011af8011bf8011cf8011df8011ef8011ff80120f80121f80122f80123f80124f80125f80126f80127f80128"),
        ("packed nibble strings", ""),
        ("packed hex strings", "f80919fc046576656efb083eb0f4a1b2c3d4e5fc036f6464fb883eb0f4a1b2c3d4effc096d6978656463617365fc083365623046344131fc07616c6c63617073fb08abcdef0123456789"),
        ("jids all domain types", ""),
        ("non-token strings short and long", ""),
        ("string content", "f802ed75fc26636f6e7465c3ba646f20646520746578746f20636f6d206163656e746f7320c3a920f09f9880"),
        ("long string content", ""),
        ("bytes content", ""),
        ("nested children", "f80a1908fb043eb0aaaa045a110316cbf802f8049e0cfaff875511999998888f03f801f8026cfc03010203f801fc05656d707479"),
        ("empty attrs empty content list", "f8021ff800"),
        ("list16 children", ""),
    ];

    for (name, expected_hex) in fixtures {
        let input_bytes = hex_to_bytes(expected_hex);
        let decoded = decode_binary_node(&input_bytes)
            .unwrap_or_else(|e| panic!("Failed to decode fixture '{}': {}", name, e));
        let re_encoded = encode_binary_node(&decoded);
        let output_hex = bytes_to_hex(&re_encoded);
        assert_eq!(&output_hex, expected_hex, "Fixture round-trip mismatch: {}", name);
    }
}
